        ggml_backend_opencl_ਬਫਰ_context * ctx = (ggml_backend_opencl_ਬਫਰ_context *) ਬਫਰ->context;
        ggml_tensor_extra_cl_q4_K * extra = ctx->ggml_opencl_alloc_ਆਰਜ਼ੀ_tensor_extra_q4_K();

        size_t ਮਾਪ_d = ggml_nelements(tensor)/ggml_blck_ਮਾਪ(tensor->type)*ਆਕਾਰ(ggml_fp16_t);
        size_t ਮਾਪ_dm = ggml_nelements(tensor)/ggml_blck_ਮਾਪ(tensor->type)*ਆਕਾਰ(ggml_fp16_t);
        size_t ਮਾਪ_s = ggml_nelements(tensor)/ggml_blck_ਮਾਪ(tensor->type)*(3 * ggml_blck_ਮਾਪ(tensor->type) / 64);
        size_t ਮਾਪ_q = ggml_nelements(tensor)/ggml_blck_ਮਾਪ(tensor->type)*ggml_blck_ਮਾਪ(tensor->type)/2;
        GGML_ASSERT(ਮਾਪ_d + ਮਾਪ_dm + ਮਾਪ_s + ਮਾਪ_q == ggml_nbytes(tensor) && "Incorrect tensor size");

        cl_int err;
        cl_mem ਅੰਕੜੇ_device = ggml_cl_create_ਆਰਜ਼ੀ_upload_ਬਫਰ(context, queue, ggml_nbytes(tensor), ਅੰਕੜੇ, tensor->name);
        GGML_ASSERT(ਅੰਕੜੇ_device != ਨਿਰਾ && "q4_K set_tensor: temp upload buffer alloc failed");

        cl_ਬਫਰ_region region;

