            ਪੂਰਨ ne01 = tensor->ne[1];
            ਪੂਰਨ ne02 = tensor->ne[2];

            cl_uchar ਨਕਾਬ_0_F = 0x0F;
            cl_uchar ਨਕਾਬ_F0 = 0xF0;
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 0, ਆਕਾਰ(cl_mem), &ਅੰਕੜੇ_device));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 1, ਆਕਾਰ(cl_mem), &extra->q));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 2, ਆਕਾਰ(cl_mem), &extra->d));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 3, ਆਕਾਰ(cl_mem), &extra->dm));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 4, ਆਕਾਰ(cl_mem), &extra->s));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 5, ਆਕਾਰ(ਪੂਰਨ), &ne00));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 6, ਆਕਾਰ(ਪੂਰਨ), &ne01));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 7, ਆਕਾਰ(cl_uchar), &ਨਕਾਬ_0_F));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 8, ਆਕਾਰ(cl_uchar), &ਨਕਾਬ_F0));

            size_t global_work_ਮਾਪ[] = {static_cast<size_t>(((ne01 + 63) / 64) * 64), static_cast<size_t>(ne00 / 256), static_cast<size_t>(ne02)};
            size_t local_work_ਮਾਪ[] = {64, 1, 1};

            cl_event evt;
            CL_CHECK(cl_ਕਤਾਰ_ਵਿੱਚ_ਪਾਓ_NDRange_Kernel(queue, kernel, 3, ਨਿਰਾ, global_work_ਮਾਪ, local_work_ਮਾਪ, 0, ਨਿਰਾ, &evt));
            CL_CHECK(clWaitForEvents(1, &evt));
            CL_CHECK(clReleaseMemObject(ਅੰਕੜੇ_device));

            cl_image_format img_format_q = {CL_R, CL_UNSIGNED_INT32};
            cl_image_desc img_desc_q = {
                CL_MEM_OBJECT_IMAGE1_D_ਬਫਰ,
                static_cast<size_t>(ggml_nelements(tensor) / 8),
                0, 0, 0, 0, 0, 0, 0,
                { extra->q }
            };
            extra->q_img = clCreateImage(context, CL_MEM_READ_ONLY, &img_format_q, &img_desc_q, ਨਿਰਾ, &err);
            CL_CHECK(err);
