            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 1, ਆਕਾਰ(cl_mem), &extra->q));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 2, ਆਕਾਰ(cl_mem), &extra->d));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 3, ਆਕਾਰ(cl_mem), &extra->dm));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 4, ਆਕਾਰ(cl_mem), &extra->s));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 5, ਆਕਾਰ(ਪੂਰਨ), &ne00));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(tk, 6, ਆਕਾਰ(ਪੂਰਨ), &ne01));

            size_t gws[] = {static_cast<size_t>(((ne01 + 63) / 64) * 64), static_cast<size_t>(ne00 / 256), static_cast<size_t>(ne02)};
            size_t lws[] = {64, 1, 1};

            cl_event tevt;
            CL_CHECK(cl_ਕਤਾਰ_ਵਿੱਚ_ਪਾਓ_NDRange_Kernel(queue, tk, 3, ਨਿਰਾ, gws, lws, 0, ਨਿਰਾ, &tevt));
            CL_CHECK(clWaitForEvents(1, &tevt));
            CL_CHECK(clReleaseMemObject(ਅੰਕੜੇ_device));

