            cl_uchar ਨਕਾਬ_0_F = 0x0F;
            cl_uchar ਨਕਾਬ_F0 = 0xF0;

            cl_kernel kernel = backend_ctx->kernel_restore_ਖੰਡ_iq4_nl_noshuffle;
            cl_ulong n_blk = ggml_nelements(tensor)/ggml_blck_ਮਾਪ(tensor->type);

            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 0, ਆਕਾਰ(cl_mem),   &buf_trans_q.ਬਫਰ));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 1, ਆਕਾਰ(cl_mem),   &buf_trans_d.ਬਫਰ));
