                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(ਪੂਰਨ),       &ne00));
                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(ਪੂਰਨ),       &ne01));
