            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel,  5, ਆਕਾਰ(cl_ulong), &offset2));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel,  6, ਆਕਾਰ(cl_mem),   &extrad->ਅੰਕੜੇ_device));
