            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 13, ਆਕਾਰ(ਪੂਰਨ),      &ne10));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 14, ਆਕਾਰ(ਪੂਰਨ),      &ne11));
            CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, 15, ਆਕਾਰ(ਪੂਰਨ),      &ne12));
