                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(cl_mem),    &extra0_q4_1->d));
                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(cl_mem),    &extra0_q4_1->m));
