                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(ਪੂਰਨ),       &ne00));
                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(ਪੂਰਨ),       &ne01));
                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(cl_uint),   &backend_ctx->adreno_use_moe_ragged));
                    CL_CHECK(cl_ਸੈੱਟ_Kernel_Arg(kernel, arg_idx++, ਆਕਾਰ(cl_uint),   &backend_ctx->adreno_moe_ragged_skip_gran));

